from build123d import *
import math

block_size = 80.0
hole_diameter = 28.0
counterbore_diameter = 40.0
counterbore_depth = 10.0
chamfer_angle = 30.0
chamfer_distance = counterbore_depth * math.tan(math.radians(chamfer_angle))

solid_body = Box(block_size, block_size, block_size)

for axis in [Axis.X, Axis.Y, Axis.Z]:
    for sign in [1, -1]:
        if axis == Axis.X:
            cb = Pos(sign * (block_size/2 - counterbore_depth/2), 0, 0) * Rot(0, 90, 0) * Cylinder(counterbore_diameter/2, counterbore_depth)
        elif axis == Axis.Y:
            cb = Pos(0, sign * (block_size/2 - counterbore_depth/2), 0) * Rot(-90, 0, 0) * Cylinder(counterbore_diameter/2, counterbore_depth)
        else:
            cb = Pos(0, 0, sign * (block_size/2 - counterbore_depth/2)) * Cylinder(counterbore_diameter/2, counterbore_depth)
        solid_body = solid_body - cb

for axis in [Axis.X, Axis.Y, Axis.Z]:
    if axis == Axis.X:
        th = Rot(0, 90, 0) * Cylinder(hole_diameter/2, block_size + 2)
    elif axis == Axis.Y:
        th = Rot(-90, 0, 0) * Cylinder(hole_diameter/2, block_size + 2)
    else:
        th = Cylinder(hole_diameter/2, block_size + 2)
    solid_body = solid_body - th

solid_body = chamfer(solid_body.edges(), chamfer_distance)

part = solid_body
part.name = "block_with_counterbored_holes"
export_step(part, "output.step")

from build123d import *
import math

outer_radius = 40.0
inner_radius = 10.0
thickness = 10.0
fillet_radius = 3.0
hole_diameter = 5.0

def hypocycloid(t, r1, r2):
    return ((r1 - r2) * math.cos(t) + r2 * math.cos(r1 / r2 * t - t),
            (r1 - r2) * math.sin(t) + r2 * math.sin(-(r1 / r2 * t - t)))

def epicycloid(t, r1, r2):
    return ((r1 + r2) * math.cos(t) - r2 * math.cos(r1 / r2 * t + t),
            (r1 + r2) * math.sin(t) - r2 * math.sin(r1 / r2 * t + t))

def gear_point(t, r1=outer_radius, r2=inner_radius):
    if (-1) ** (1 + math.floor(t / (2 * math.pi) * (r1 / r2))) < 0:
        return epicycloid(t, r1, r2)
    return hypocycloid(t, r1, r2)

points = [gear_point(t * 2 * math.pi, outer_radius, inner_radius) for t in [i/100 for i in range(101)]]

with BuildPart() as p:
    with BuildSketch() as s:
        Polygon(*points)
    extrude(amount=thickness)

solid_body = p.part
solid_body = fillet(solid_body.edges(), fillet_radius)

hole_positions = [(0, 0)] + [
    (outer_radius * math.cos(math.radians(a)), outer_radius * math.sin(math.radians(a)))
    for a in [0, 120, 240]
]

for x, y in hole_positions:
    solid_body = solid_body - Pos(x, y, 0) * Cylinder(hole_diameter/2, thickness * 2)

part = solid_body
part.name = "gear"
export_step(part, "output.step")
